// Cache em duas partes (v339):
//  CODIGO (paginas, scripts, estilos, dados): um cache por versao, baixado inteiro ao instalar; as paginas abrem dele na hora.
//    A versao nova instala em segundo plano e vale a partir da proxima troca de tela (o botao ATUALIZAR da capa forca a troca).
//  MIDIA (imagens, fontes): um cache so, que NAO e apagado a cada versao. REV guarda a impressao digital de cada arquivo;
//    ao instalar, so baixa o que mudou ou falta (antes: 85 MB de novo a cada versao, disputando a rede com o jogo).
//  REV e gerado por tools/swrev.mjs: rode `node tools/swrev.mjs` sempre que mudar ou acrescentar uma imagem.
const MEDIA='bd1-media', REVKEY='/__bd1_media_rev__';
const keyOf=u=>{const x=new URL(u,self.location);return x.origin+x.pathname};
const isCode=u=>{const p=new URL(u,self.location).pathname;return /\/$/.test(p)||/\.(html|js|css|json|webmanifest)$/.test(p)};
const relOf=u=>new URL(u,self.location).pathname.slice(new URL('./',self.location).pathname.length);
// executa fn em no maximo n tarefas ao mesmo tempo (nao satura a rede do aparelho)
async function pool(list,n,fn,strict){let i=0;await Promise.all(Array.from({length:n},async()=>{while(i<list.length){const x=list[i++];try{await fn(x)}catch(e){if(strict)throw e}}}))}
async function sha(buf){const h=await crypto.subtle.digest('SHA-1',buf);return [...new Uint8Array(h)].slice(0,5).map(b=>b.toString(16).padStart(2,'0')).join('')}
// o codigo tem que vir inteiro: se algum arquivo falhar, a instalacao falha e a versao anterior continua valendo (tenta de novo depois)
async function fillCode(){const c=await caches.open(CACHE);await pool(ASSETS.filter(isCode),6,async a=>{const r=await fetch(a,{cache:'reload'});if(!r.ok)throw new Error(a);await c.put(keyOf(a),r)},true)}
async function fillMedia(){
  const c=await caches.open(MEDIA);let have={};try{const r=await c.match(REVKEY);if(r)have=await r.json()}catch(e){}
  const todo=ASSETS.filter(a=>!isCode(a)).filter(a=>{const k=relOf(a);return have[k]!==REV[k]});
  await pool(todo,4,async a=>{const k=relOf(a),key=keyOf(a);
    // vindo de uma versao antiga (cache unico): reaproveita o arquivo se for igual ao atual, sem baixar de novo
    let old=await caches.match(key);if(old&&REV[k]){const b=await old.clone().arrayBuffer();if(await sha(b)===REV[k]){await c.put(key,old);have[k]=REV[k];return}}
    const r=await fetch(a,{cache:'reload'});if(!r.ok)return;await c.put(key,r);have[k]=REV[k]||'?'});
  await c.put(REVKEY,new Response(JSON.stringify(have),{headers:{'content-type':'application/json'}}));
}
self.addEventListener('install',e=>e.waitUntil(Promise.all([fillCode(),fillMedia()]).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil((async()=>{
  const ks=await caches.keys(),old=ks.filter(k=>k!==CACHE&&k!==MEDIA);await Promise.all(old.map(k=>caches.delete(k)));await self.clients.claim();
  if(old.length){const cs=await self.clients.matchAll({type:'window'});cs.forEach(c=>c.postMessage({type:'updated'}))}
})()));
self.addEventListener('fetch',e=>{
  const req=e.request; if(req.method!=='GET'||!req.url.startsWith(self.location.origin)||/\/sw\.js$/.test(new URL(req.url).pathname))return;
  const key=keyOf(req.url),code=req.mode==='navigate'||isCode(req.url);
  if(!code&&!/\.(png|webp|jpe?g|gif|svg|woff2?|ttf|ico|mp3|ogg|wav)$/.test(new URL(req.url).pathname))return;   // so arquivos do jogo; o resto (API, etc.) vai direto para a rede
  e.respondWith((async()=>{
    const c=await caches.open(code?CACHE:MEDIA),hit=await c.match(key);if(hit)return hit;
    try{const r=await fetch(req);if(r.ok&&r.type==='basic'&&!req.headers.has('range'))e.waitUntil(c.put(key,r.clone()));return r}catch(err){return Response.error()}
  })());
});
